// mnj <= l ^ ret b=0：未满足/b=1：已满足
// y in V

void clean_dfs(){
	for(int i = 29; i >= 0; i--){
		g[i][0] = g[i][1] = -2;
	}
}

int dfs(int p, bool b, int & mn, int & l, int & v1, int & v2){
	if(p == -1) return (b ? 0 : -1);
	if(g[p][b] != -2) return g[p][b];
	int res = inf, bt = l & (1 << p), mb = mn & (1 << p);
	bool b1 = ((v1 & (1 << p)) == 0) || ((v1 & (1 << p)) && (v2 & (1 << p)));
	bool b2 = ((v1 & (1 << p)) == 0) || ((v1 & (1 << p)) && (v2 & (1 << p)) == 0);
	if(b1){
		int rt = -1;
		if(b){
			rt = dfs(p-1, 1, mn, l, v1, v2);
		}
		else if(mn == -1 || mb < (bt^(1 << p))){
			rt = dfs(p-1, 1, mn, l, v1, v2);
		}
		else if(mb == (bt^(1 << p))){
			rt = dfs(p-1, b, mn, l, v1, v2);
		}
		if(rt != -1) res = min(res, rt|(1 << p));
	}
	if(b2){
		int rt = -1;
		if(b){
			rt = dfs(p-1, 1, mn, l, v1, v2);
		}
		else if(mn == -1 || mb < bt){
			rt = dfs(p-1, 1, mn, l, v1, v2);
		}
		else if(mb == bt){
			rt = dfs(p-1, b, mn, l, v1, v2);
		}
		if(rt != -1) res = min(res, rt);
	}
	return g[p][b] = (res == inf ? -1 : res);
}
