			continue;
		}
		ans = 1; v1 = v2 = 0;
		for(int i = 1; i < n; i++){
			f[i] = ans;
			if(hgb[i] == -1) continue;
			if((v1&hgb[i]) && (v2&hgb[i]) != hgv[i]){
				ans++; v1 = v2 = 0;
			}
			else{
