					s = a[i];
					cnt++;
				}
			}
			if(cnt+1 == ans) fg = 1;
		}
		else{
			for(int i = 1; i < n; i++){
				v1 = v2 = 0; mn[i] = inf;
				for(int j = i-1; j >= 0; j--){
					if(f[j] < f[i]-1) break;
					if(f[j] == f[i]-1 && mn[j] != inf){
						int nv2 = v2^a[i];
						int nl = a[i]^a[j+1];
						int m1 = mn[j]-1;
						clean_dfs();
						int rt = dfs(29, 0, m1, nl, v1, nv2);
						if(rt != -1) mn[i] = min(mn[i], rt);
					}
					if(hgb[j] != -1 && (v1&hgb[j]) && (v2&hgb[j]) != hgv[j]) break;
					if(hgb[j] != -1) v1 |= hgb[j], v2 |= hgv[j];
				}
			}
			for(int i = n; i >= 1; i--){
				if(i < n && a[i] > a[i+1]) break;
				if(f[i-1] == ans-1 && mn[i-1] <= a[i]){
					fg = 1;
					break;
				}
			}
		}
		cout << ans-fg << '\n';
	}
	return 0;
}
